action.code:
int idx = 0;
TreeNode* node = root;
int outIdx = 0;
for (int i = 0; i < encLen; ++i) {
    int bit = encoded[i];
    if (bit == 0) {
        node = node->left;
    } else {
        node = node->right;
    }
    if (node->left == nullptr && node->right == nullptr) {
        decoded[outIdx++] = node->val;
        ++decLen;
        node = root;
    }
}

